<?php $m=$args['model']??array();$state=$m['google_state']??'unavailable';$notice=$m['google_notice']??null; ?>
<section class="dzn-tp-section" aria-labelledby="tp-google"><h2 id="tp-google">اتصال Google Calendar</h2><p>این اتصال برای آماده‌ماندن حساب و ساخت رویداد تقویم و پیوند Meet پیش از تأیید کلاس لازم است.</p><?php if(is_array($notice)&&count($notice)===3):?><div class="dzn-tp-<?php echo esc_attr($notice[0]==='success'?'success':'unavailable'); ?>" role="<?php echo esc_attr($notice[0]==='success'?'status':'alert'); ?>"><strong><?php echo esc_html($notice[1]); ?></strong><p><?php echo esc_html($notice[2]); ?></p></div><?php endif;?><p>وضعیت: <?php echo esc_html(array('not_connected'=>'متصل نیست','connected'=>'متصل','needs_attention'=>'نیازمند توجه','unavailable'=>'در دسترس نیست')[$state]??'در دسترس نیست'); ?></p>
<?php if($state==='connected'):?><form method="post" action="<?php echo esc_url($m['google_sync_url']??''); ?>"><input type="hidden" name="_wpnonce" value="<?php echo esc_attr($m['google_sync_nonce']??''); ?>"><button class="dzn-button" type="submit">همگام‌سازی و بازبینی</button></form><form method="post" action="<?php echo esc_url($m['google_disconnect_url']??''); ?>"><input type="hidden" name="_wpnonce" value="<?php echo esc_attr($m['google_disconnect_nonce']??''); ?>"><button type="submit">قطع اتصال</button></form>
<?php elseif($state!=='unavailable'):?><form method="post" action="<?php echo esc_url($m['google_action_url']??''); ?>"><input type="hidden" name="_wpnonce" value="<?php echo esc_attr($m['google_nonce']??''); ?>"><button class="dzn-button" type="submit">اتصال Google</button></form><?php else:?><p>تنظیمات اتصال Google هنوز در دسترس نیست.</p><?php endif;?></section>
